const crypto = require('crypto');
const https = require('https');
const nodemailer = require('nodemailer');

const overdue = Array.isArray($input.first.json) ? $input.first.json : [];
const secret = process.env.LENDLOOP_HMAC_SECRET || '';
const results = [];

function postResult(result) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(result);
    const timestamp = Math.floor(Date.now() / 1000);
    const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
    const req = https.request(
      {
        hostname: new URL(process.env.CONVEX_SITE_URL).hostname,
        path: '/api/n8n/reminder-result',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-LendLoop-Timestamp': String(timestamp),
          'X-LendLoop-Signature': signature,
        },
      },
      (res) => {
        res.resume();
        res.on('end', resolve);
      },
    );
    req.on('error', reject);
    req.end(body);
  });
}

(async () => {
  for (const loan of overdue) {
    const result = { key: loan.reminderKey, loanId: loan.loanId, status: 'sent', detail: null };
    try {
      const transporter = nodemailer.createTransport({ jsonTransport: true });
      await transporter.sendMail({
        from: 'LendLoop <noreply@lendloop.local>',
        to: loan.borrower.email,
        subject: `LendLoop reminder: ${loan.toolName}`,
        text: `This is a friendly reminder that you borrowed ${loan.toolName}.`,
      });
      await postResult(result);
      results.push(result);
    } catch (e) {
      results.push({ key: loan.reminderKey, loanId: loan.loanId, status: 'failed', detail: String(e) });
    }
  }
  return [{ json: { processed: results.length } }];
})().then(() => [{ json: { processed: results.length } }]).catch(() => [{ json: { processed: 0 } }]);
